const body = $json.body || $json;
if (!body.email && !body.phone) {
  throw new Error('Invalid cart payload: Missing customer contact details');
}
const cartValue = parseFloat(body.total_price || body.cart_value || 0);
const items = (body.line_items || []).map(item => item.title || item.name).join(', ');

return [{
  json: {
    checkout_id: body.id || 'chk_' + Date.now(),
    customer_name: (body.customer ? body.customer.first_name : body.name) || 'there',
    email: (body.email || '').toLowerCase().trim(),
    phone: (body.phone || '').trim(),
    cart_value: cartValue,
    items_summary: items || 'your cart items',
    is_high_value: cartValue >= 75,
    discount_tier: cartValue >= 100 ? 'VIP20' : 'SAVE10',
    discount_percentage: cartValue >= 100 ? 20 : 10
  }
}];

